-- Open hay / mineral / feed to-dos: rename their stops, drop any duplicate the
-- rename creates, and rebuild the title and stop list from the new names.
UPDATE tasks SET
    followup_stops = replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(followup_stops, '"Behind the barn"', '"Behind the Barn"'), '"Horse field"', '"Horse Field"'), '"Lake field"', '"Lake Field"'), '"Church field"', '"Church Field"'), '"Dr. Berrys"', '"Dr. Berry''s"'), '"Woodville"', '"Woodville Catfish Pond Field"'), '"State line"', '"State Line"'), '"Kill cows"', '"Kill Cow Field"'), '"Kill cow field"', '"Kill Cow Field"'), '"Sterling house"', '"Sterling House Field"'), '"Sterling bulls"', '"Sterling Bulls"'), '"Weaning pen feeder"', '"Weaning Pen"'), '"Sage hill heifers"', '"Sage Hill Heifers"'), '"Sage hill commercial cows"', '"Sage Hill Commercial Cows"'), '"Sage hill front field"', '"Sage Hill Front Field"'), '"Sage hill grass trap"', '"Sage Hill Grass Trap"'), '"Sage hill past blown down barn"', '"Sage Hill Past Blown Down Barn"'), '"Sage hill past iron gates"', '"Sage Hill Past Iron Gates"'), '"Sage hill well field"', '"Sage Hill Well Field"'), '"Woodville middle field"', '"Woodville Middle Field"'),
    followup_done = replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(followup_done, '"Behind the barn"', '"Behind the Barn"'), '"Horse field"', '"Horse Field"'), '"Lake field"', '"Lake Field"'), '"Church field"', '"Church Field"'), '"Dr. Berrys"', '"Dr. Berry''s"'), '"Woodville"', '"Woodville Catfish Pond Field"'), '"State line"', '"State Line"'), '"Kill cows"', '"Kill Cow Field"'), '"Kill cow field"', '"Kill Cow Field"'), '"Sterling house"', '"Sterling House Field"'), '"Sterling bulls"', '"Sterling Bulls"'), '"Weaning pen feeder"', '"Weaning Pen"'), '"Sage hill heifers"', '"Sage Hill Heifers"'), '"Sage hill commercial cows"', '"Sage Hill Commercial Cows"'), '"Sage hill front field"', '"Sage Hill Front Field"'), '"Sage hill grass trap"', '"Sage Hill Grass Trap"'), '"Sage hill past blown down barn"', '"Sage Hill Past Blown Down Barn"'), '"Sage hill past iron gates"', '"Sage Hill Past Iron Gates"'), '"Sage hill well field"', '"Sage Hill Well Field"'), '"Woodville middle field"', '"Woodville Middle Field"')
  WHERE followup_key IS NOT NULL AND status = 'open';

UPDATE tasks SET followup_stops = (
    SELECT json_group_array(value) FROM (
      SELECT value, MIN(key) AS k FROM json_each(tasks.followup_stops) GROUP BY value ORDER BY k))
  WHERE followup_key IS NOT NULL AND status = 'open' AND json_valid(followup_stops);

UPDATE tasks SET
    title = substr(followup_key || ': ' || (SELECT group_concat(value, ', ') FROM json_each(tasks.followup_stops)), 1, 160),
    description = 'Stops:' || char(10) ||
      (SELECT group_concat('• ' || value, char(10)) FROM json_each(tasks.followup_stops)) ||
      char(10) || char(10) || 'Stop names updated to match the guides.'
  WHERE followup_key IS NOT NULL AND status = 'open' AND json_valid(followup_stops)
    AND json_array_length(followup_stops) > 0;
